PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE COLLATE NOCASE,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'student' CHECK(role IN ('student','institute','employer','admin')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS student_profiles (user_id INTEGER PRIMARY KEY,branch TEXT NOT NULL DEFAULT 'Computer Science',year INTEGER NOT NULL DEFAULT 2,cgpa REAL,career_direction TEXT DEFAULT 'Software Engineering',preferred_location TEXT DEFAULT 'India · Remote',open_to_opportunities INTEGER NOT NULL DEFAULT 1,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS skills (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL UNIQUE,category TEXT,demand_level TEXT DEFAULT 'medium');
CREATE TABLE IF NOT EXISTS user_skills (user_id INTEGER NOT NULL,skill_id INTEGER NOT NULL,level REAL NOT NULL DEFAULT 0,evidence TEXT,verified INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(user_id,skill_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS study_units (id INTEGER PRIMARY KEY AUTOINCREMENT,branch TEXT NOT NULL,year INTEGER NOT NULL,title TEXT NOT NULL,description TEXT,resource_url TEXT,resource_type TEXT DEFAULT 'lesson');
CREATE TABLE IF NOT EXISTS opportunities (id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,employer TEXT NOT NULL,location TEXT,type TEXT NOT NULL CHECK(type IN ('internship','placement')),stipend_or_package TEXT,duration TEXT,description TEXT,skills TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS applications (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,opportunity_id INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'applied' CHECK(status IN ('saved','applied','screening','interview','offer','rejected')),applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,opportunity_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(opportunity_id) REFERENCES opportunities(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS progress (user_id INTEGER NOT NULL,study_unit_id INTEGER NOT NULL,completed INTEGER NOT NULL DEFAULT 0,completed_at TEXT,PRIMARY KEY(user_id,study_unit_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(study_unit_id) REFERENCES study_units(id) ON DELETE CASCADE);